184:     // ───────────── entry point ─────────────
185:     pub fn draw_window(&mut self, ui: &mut Ui) {
186:         if !IS_WEB {
187:             clear_drop_targets();
188:             return self.draw_files_window(ui);
189:         }
190:         clear_drop_targets();
191:         let screen = ui.max_rect();
192:         let p = ui.painter().clone();
193:         self.draw_desktop(&p, screen);
194:         self.shell_focus(ui, screen);
195:         for id in self.shell.z.clone() {
196:             match id {
197:                 AppId::Files => {
198:                     if !(self.win_closed || self.win_min) {
199:                         self.draw_files_window(ui);
200:                     }
201:                 }
202:                 _ => self.draw_app(ui, id, screen),
203:             }
204:         }
205:         self.draw_app_menu(ui, screen);
206:         self.draw_dock(ui, screen);
207:         self.draw_topbar(ui, screen);
208:         let b = self.shell.brightness;
209:         if b < 0.99 {
210:             let lp = ui.ctx().layer_painter(egui::LayerId::new(egui::Order::Tooltip, Id::new("dim")));
211:             lp.rect_filled(screen, 0.0, Color32::from_black_alpha(((1.0 - b) * 150.0) as u8));
212:         }
213:     }
214: 
215:     /// Pressing inside a window raises it; the top bar and dock never steal focus.
216:     fn shell_focus(&mut self, ui: &Ui, screen: Rect) {
217:         let Some(pos) = ui.input(|i| if i.pointer.primary_pressed() { i.pointer.interact_pos() } else { None }) else { return };
218:         if pos.y < TOPBAR_H || pos.y > screen.bottom() - 70.0 {
219:             return;
220:         }
221:         for id in self.shell.z.clone().into_iter().rev() {
222:             let r = match id {
223:                 AppId::Files => {
224:                     if self.win_closed || self.win_min {
225:                         continue;
226:                     }
227:                     self.window_rect(screen)
228:                 }
229:                 other => {
230:                     let w = self.app_win(other).unwrap();
231:                     if !w.open || w.min {
232:                         continue;
233:                     }
234:                     w.rect
235:                 }
236:             };
237:             if r.contains(pos) {
238:                 if self.focused_app() != id {
239:                     self.raise(id);
240:                 }
241:                 break;
242:             }
243:         }
244:     }
245: 
246:     // ───────────── app window frame ─────────────
247:     /// Unified macOS-style window: the sidebar runs the full height (traffic lights live in it), the toolbar shares the
248:     /// surface with the content (no title bar, no divider) and the whole thing resizes from every edge.
249:     fn draw_app(&mut self, ui: &mut Ui, id: AppId, screen: Rect) {
250:         let (open, min) = {
251:             let w = self.app_win(id).unwrap();
252:             (w.open, w.min)
253:         };
254:         if !open || min {
255:             return;
256:         }
257:         let avail = Rect::from_min_max(pos2(screen.left(), screen.top() + TOPBAR_H), pos2(screen.right(), screen.bottom() - 6.0));
258:         let n_open = self.shell.z.iter().position(|x| *x == id).unwrap_or(0) as f32;
259:         {
260:             let w = self.app_win_mut(id);
261:             if !w.placed {
262:                 let size = vec2(w.rect.width().min(avail.width() - 40.0), w.rect.height().min(avail.height() - DOCK_H * 0.6));
263:                 let c = avail.center() + vec2(40.0 + n_open * 18.0, 10.0 + n_open * 14.0 - 30.0);
264:                 w.rect = Rect::from_center_size(c, size);
265:                 w.placed = true;
266:             }
267:         }
268:         let (rect, born, restore, side_pref) = {
269:             let w = self.app_win(id).unwrap();
270:             (w.rect, w.born, w.restore, w.side)
271:         };
272:         let active = self.focused_app() == id;
273:         let th = self.th.clone();
274:         let ctx = ui.ctx().clone();
275:         let age = (self.time - born) as f32;
276:         let pop = if self.lib(|l| l.settings.reduce_motion) { 1.0 } else { spring_out(age) };
277:         if age < 0.7 {
278:             ctx.request_repaint();
279:         }
280:         let off = vec2(0.0, (1.0 - pop) * 28.0);
281:         let mut cui = ui.new_child(egui::UiBuilder::new().max_rect(screen));
282:         cui.set_opacity((age * 7.0).clamp(0.0, 1.0));
283:         let p = cui.painter().clone();
284:         let shown = rect.translate(off);
285:         elevate(&p, &th, shown, R_WIN, if active { 5 } else { 3 });
286:         // glass body (same recipe as the Files window)
287:         let (_, sz, blur) = self.active_wall();
288:         if let Some(b) = blur {
289:             let suv = cover_uv(sz[0], sz[1], screen);
290:             let f = |pt: Pos2| pos2(suv.min.x + (pt.x - screen.min.x) / screen.width() * suv.width(), suv.min.y + (pt.y - screen.min.y) / screen.height() * suv.height());
291:             textured_rrect(&p, shown, R_WIN, b, Rect::from_min_max(f(shown.min), f(shown.max)), Color32::from_white_alpha(if th.dark { 210 } else { 255 }));
292:         }
293:         grad_fill(&p, shown, R_WIN, th.window_top, th.window_bottom);
294:         // responsive: the sidebar folds away on narrow windows and comes back with a spring
295:         let want_side = side_pref && shown.width() >= 720.0;
296:         let sf = spring_to(&ctx, ("appside", id), if want_side { 1.0 } else { 0.0 }, 260.0, 26.0).clamp(0.0, 1.0);
297:         let side_w = SIDEBAR_W * sf;
298:         let sb = Rect::from_min_size(shown.min, vec2(side_w, shown.height()));
299:         let stage = Rect::from_min_max(pos2(shown.min.x + side_w, shown.min.y), shown.max);
300:         if side_w > 1.0 {
301:             let pp = p.with_clip_rect(sb);
302:             grad_fill(&pp, Rect::from_min_max(shown.min, pos2(shown.min.x + side_w + R_WIN + 4.0, shown.max.y)), R_WIN, th.sidebar_top, th.sidebar_bottom);
303:         }
304:         {
305:             let pp = p.with_clip_rect(stage);
306:             grad_fill(&pp, Rect::from_min_max(pos2(stage.min.x - R_WIN - 4.0, shown.min.y), shown.max), R_WIN, th.content_top, th.content_bottom);
307:         }
308:         // toolbar drag region (created first so controls on top win)
309:         let bar = Rect::from_min_size(stage.min, vec2(stage.width(), APPBAR_H));
310:         let drag = Rect::from_min_size(shown.min, vec2(shown.width(), APPBAR_H));
311:         let tresp = cui.interact(drag, Id::new(("apptitle", id)), Sense::click_and_drag());
312:         let mut maximise = tresp.double_clicked();
313:         if tresp.dragged() && restore.is_none() {
314:             let d = tresp.drag_delta();
315:             let w = self.app_win_mut(id);
316:             w.rect = w.rect.translate(d);
317:             w.rect = w.rect.translate(vec2(0.0, (avail.top() - w.rect.top()).max(0.0)));
318:         }
319:         // traffic lights: in the sidebar when it is there, in the toolbar when it folds
320:         let cy = shown.top() + APPBAR_H / 2.0;
321:         let tl_x = shown.left() + 20.0;
322:         let (c1, c2, c3) = self.app_traffic(&cui, pos2(tl_x, cy), id, active);
323:         let mut do_close = c1;
324:         let mut do_min = c2;
325:         if c3 {
326:             maximise = true;
327:         }
328:         // sidebar toggle: owned by the toolbar, right after the traffic lights when the sidebar is folded
329:         let tx = bar.left() + 14.0 + (1.0 - sf) * 78.0 - if sf > 0.5 { 0.0 } else { 0.0 };
330:         let tx = if side_w > 40.0 { tx.max(bar.left() + 14.0) } else { shown.left() + 20.0 + 78.0 };
331:         let toggle = Rect::from_min_size(pos2(tx, cy - 17.0), vec2(34.0, 34.0));
332:         if self.icon_button(&cui, toggle, "sidebar-minimalistic", &format!("tb-side-{:?}", id), if side_pref { Btn::Raised } else { Btn::Tonal }, true).on_hover_text("Toggle sidebar  Ctrl+\\").clicked() {
333:             self.app_win_mut(id).side = !side_pref;
334:         }
335:         let side_body = Rect::from_min_max(pos2(shown.left(), shown.top() + 54.0), pos2(shown.left() + SIDEBAR_W, shown.bottom() - 10.0));
336:         let content = Rect::from_min_max(pos2(stage.left(), bar.bottom()), shown.max);
337:         let fr = crate::appkit::Frame { win: shown, side: sb, side_body, bar, stage: content, lead_x: toggle.right() + 12.0, right_x: bar.right() - 14.0, active };
338:         let mut cp = cui.new_child(egui::UiBuilder::new().max_rect(shown));
339:         cp.set_clip_rect(shown.intersect(screen));
340:         match id {
341:             AppId::Terminal => self.draw_terminal(&mut cp, &fr),
342:             AppId::Photos => self.draw_photos(&mut cp, &fr),
343:             AppId::Files => {}
344:         }
345:         if self.shell.settings.map(|s| s.0) == Some(id) {
346:             match id {
347:                 AppId::Terminal => self.term_settings(&mut cp, shown),
348:                 AppId::Photos => self.photos_settings(&mut cp, shown),
349:                 AppId::Files => {}
350:             }
351:         }
352:         // edge + corner resize (all eight handles)
353:         let min_sz = vec2(520.0, 340.0);
354:         if let Some((dir, d)) = self.resize_handles(&cui, id, shown) {
355:             if restore.is_none() {
356:                 let w = self.app_win_mut(id);
357:                 if dir.0 > 0.0 {
358:                     w.rect.max.x = (w.rect.max.x + d.x).max(w.rect.min.x + min_sz.x);
359:                 } else if dir.0 < 0.0 {
360:                     w.rect.min.x = (w.rect.min.x + d.x).min(w.rect.max.x - min_sz.x);
361:                 }
362:                 if dir.1 > 0.0 {
363:                     w.rect.max.y = (w.rect.max.y + d.y).max(w.rect.min.y + min_sz.y);
364:                 } else if dir.1 < 0.0 {
365:                     w.rect.min.y = (w.rect.min.y + d.y).min(w.rect.max.y - min_sz.y).max(avail.top());
366:                 }
367:             }
368:         }
369:         rim(&p, shown, R_WIN, 1.4, if th.dark { c(255, 255, 255, if active { 0.14 } else { 0.07 }) } else { c(255, 255, 255, 0.9) }, true, 42.0);
370:         // apply
371:         if do_close {
372:             self.app_win_mut(id).open = false;
373:             self.shell.settings = None;
374:             do_close = false;
375:         }
376:         if do_min {
377:             self.app_win_mut(id).min = true;
378:             do_min = false;
379:         }
380:         let _ = (do_close, do_min);
381:         if maximise {
382:             let w = self.app_win_mut(id);
383:             if let Some(r) = w.restore.take() {
384:                 w.rect = r;
385:             } else {
386:                 w.restore = Some(w.rect);
387:                 w.rect = avail.shrink2(vec2(8.0, 4.0));
388:             }
389:         }
390:     }
