465:     fn draw_topbar(&mut self, ui: &mut Ui, screen: Rect) {
466:         let ctx = ui.ctx().clone();
467:         let th = self.th.clone();
468:         let p = ui.painter().clone();
469:         let bar = Rect::from_min_size(screen.min, vec2(screen.width(), TOPBAR_H));
470:         let (top, bot) = if th.dark { (c(10, 14, 24, 0.66), c(10, 14, 24, 0.50)) } else { (c(255, 255, 255, 0.62), c(244, 248, 255, 0.48)) };
471:         grad_fill(&p, bar, 0.0, top, bot);
472:         p.line_segment([bar.left_bottom(), bar.right_bottom()], egui::Stroke::new(1.0, if th.dark { c(255, 255, 255, 0.07) } else { c(255, 255, 255, 0.7) }));
473:         p.line_segment([bar.left_bottom() + vec2(0.0, 1.0), bar.right_bottom() + vec2(0.0, 1.0)], egui::Stroke::new(1.0, alpha(th.shadow, if th.dark { 0.3 } else { 0.06 })));
474:         let cy = bar.center().y;
475:         let app = self.focused_app();
476:         let app = if app == AppId::Files && (self.win_closed || self.win_min) { AppId::Files } else { app };
477:         let ink = if th.dark { th.ink1 } else { th.ink1 };
478: 
479:         // logo → Smart menu
