89: /// Fanout directory for a key: 2+2 hex chars (256 ways) — `readdir` discipline.
90: pub fn fanout(key: &str) -> (String, String) {
91:     let a = key.get(0..2).unwrap_or("00").to_string();
92:     let b = key.get(2..4).unwrap_or("00").to_string();
93:     (a, b)
94: }
