134: /// Bounded LRU over memory residency (FIFO per Shotwell `Caching` note).
135: #[derive(Debug)]
136: pub struct Lru<T> {
137:     cap: usize,
138:     map: HashMap<String, T>,
139:     order: VecDeque<String>,
140: }
141: 
142: impl<T> Lru<T> {
143:     pub fn new(cap: usize) -> Self {
144:         Self { cap: cap.max(1), map: HashMap::new(), order: VecDeque::new() }
145:     }
146:     /// Insert; evicts the least-recently *seen* entry. Returns true if inserted.
147:     pub fn insert(&mut self, key: String, val: T) -> bool {
148:         if self.map.contains_key(&key) {
149:             self.map.insert(key.clone(), val);
150:             self.touch(&key);
151:             return false;
152:         }
153:         while self.map.len() >= self.cap {
154:             if let Some(old) = self.order.pop_front() {
155:                 self.map.remove(&old);
156:             } else {
157:                 break;
158:             }
159:         }
160:         self.order.push_back(key.clone());
161:         self.map.insert(key, val);
162:         true
163:     }
164:     pub fn get(&mut self, key: &str) -> Option<&T> {
165:         if !self.map.contains_key(key) {
166:             return None;
167:         }
168:         self.touch(key);
169:         self.map.get(key)
170:     }
171:     fn touch(&mut self, key: &str) {
172:         if let Some(pos) = self.order.iter().position(|k| k == key) {
173:             if let Some(k) = self.order.remove(pos) {
174:                 self.order.push_back(k);
175:             }
176:         }
177:     }
178:     pub fn len(&self) -> usize {
179:         self.map.len()
180:     }
181:     pub fn is_empty(&self) -> bool {
182:         self.map.is_empty()
183:     }
184: }
185: 
186: /// Bounded `seen` dedupe (Files `thumbs.rs LruSeen` pattern).
187: /// Stores cache keys; evicts oldest past [`SEEN_CAP`]. `insert` returns
188: /// false when the key was already seen (dedupe).
189: #[derive(Debug, Default)]
190: pub struct SeenLru {
191:     set: HashSet<String>,
192:     order: VecDeque<String>,
193: }
194: 
195: impl SeenLru {
196:     pub fn new() -> Self {
197:         Self::default()
198:     }
199:     pub fn insert(&mut self, key: String) -> bool {
200:         if !self.set.insert(key.clone()) {
201:             return false;
202:         }
203:         self.order.push_back(key);
204:         while self.order.len() > SEEN_CAP {
205:             if let Some(old) = self.order.pop_front() {
206:                 self.set.remove(&old);
207:             } else {
208:                 break;
209:             }
210:         }
211:         true
212:     }
213:     pub fn contains(&self, key: &str) -> bool {
214:         self.set.contains(key)
215:     }
216:     /// Forget every key whose value mentions `path` (edit / re-index).
217:     pub fn forget_containing(&mut self, path: &str) {
218:         if path.is_empty() {
219:             return;
220:         }
221:         // Keys are BLAKE3 hex — they never literally contain the path.
222:         // Keep the set consistent anyway: callers that tracked a path-key
223:         // prefix can clear by exact key via `remove`. This method exists so
224:         // `ThumbCache::forget(path)` keeps its contract (edit → new key
225:         // anyway via mtime/generation, so stale entries simply age out).
226:         self.set.retain(|k| !k.contains(path));
227:         self.order.retain(|k| !k.contains(path));
228:     }
229:     pub fn remove(&mut self, key: &str) {
230:         self.set.remove(key);
231:         self.order.retain(|k| k != key);
232:     }
233:     pub fn len(&self) -> usize {
234:         self.set.len()
235:     }
236:     pub fn is_empty(&self) -> bool {
237:         self.set.is_empty()
238:     }
239: }
