241: /// Big-thumb residency: at most 8 decoded above-threshold (≥512 px) rungs.
242: pub type BigPool = Lru<Vec<u8>>;
243: 
244: /// Disk LRU budget (user setting; default 500 MB).
245: #[derive(Debug)]
246: pub struct DiskLru {
247:     pub dir: PathBuf,
248:     pub budget_bytes: u64,
249: }
250: 
251: impl DiskLru {
252:     pub fn new(dir: PathBuf, budget_mb: u64) -> Self {
253:         Self { dir, budget_bytes: budget_mb.clamp(64, CACHE_CEILING_MB) << 20 }
254:     }
255:     /// Evict oldest files until the cache is under budget. Returns freed bytes.
256:     pub fn evict(&self) -> u64 {
257:         let mut total = 0u64;
258:         let mut entries: Vec<(i64, PathBuf)> = Vec::new();
259:         walk_files(&self.dir, &mut |p| {
260:             if let Ok(m) = std::fs::metadata(&p) {
261:                 total += m.len();
262:                 let t = m.modified().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i64).unwrap_or(0);
263:                 entries.push((t, p));
264:             }
265:         });
266:         entries.sort_by_key(|(t, _)| *t);
267:         let mut freed = 0u64;
268:         for (_, p) in entries {
269:             if total <= self.budget_bytes {
270:                 break;
271:             }
272:             if let Ok(m) = std::fs::metadata(&p) {
273:                 if std::fs::remove_file(&p).is_ok() {
274:                     total = total.saturating_sub(m.len());
275:                     freed += m.len();
276:                 }
277:             }
278:         }
279:         freed
280:     }
281: }
282: 
283: fn walk_files(dir: &PathBuf, f: &mut impl FnMut(PathBuf)) {
284:     if let Ok(rd) = std::fs::read_dir(dir) {
285:         for e in rd.flatten() {
286:             let p = e.path();
287:             if p.is_dir() {
288:                 walk_files(&p, f);
289:             } else {
290:                 f(p);
291:             }
292:         }
293:     }
294: }
