296: /// One visible thumb request. `key` is the BLAKE3 cache key (mtime in it).
297: #[derive(Clone, Debug)]
298: pub struct ThumbJob {
299:     pub path: String,
300:     pub key: String,
301:     pub rung: u32,
302:     pub edge: u32,
303:     pub generation: u64,
304: }
