306: /// Finished thumbnail (RGBA, on-screen size).
307: #[derive(Clone, Debug)]
308: pub struct ThumbResult {
309:     pub key: String,
310:     pub path: String,
311:     pub w: u32,
312:     pub h: u32,
313:     pub rgba: Vec<u8>,
314:     pub from_disk: bool,
315:     pub video_frame: bool,
