318: #[derive(Default)]
319: struct QueueState {
320:     queue: Vec<ThumbJob>,
321:     out: Vec<ThumbResult>,
322: }
323: 
324: struct Shared {
325:     state: Mutex<QueueState>,
326:     cv: Condvar,
327:     generation: AtomicU64,
328:     cancelled: AtomicBool,
329: }
330: 
331: impl Shared {
332:     fn lock_state(&self) -> std::sync::MutexGuard<'_, QueueState> {
333:         // Invariant: no thread panics while holding the lock; recover anyway
334:         // rather than propagate poison as a panic.
335:         self.state.lock().unwrap_or_else(|e| e.into_inner())
336:     }
337: }
