339: /// Composite cache: disk LRU + big-thumb pool + fail records + decode queue.
340: pub struct ThumbCache {
341:     pub disk: DiskLru,
342:     pub big: BigPool,
343:     /// `fail/<digest(abspath,mtime_ns)>` — failed N times.
344:     pub fails: HashMap<String, u32>,
345:     /// Bounded seen dedupe (1024). Plain field (workers own queue-side
346:     /// dedupe via generation); mutated on the UI thread.
347:     pub seen: SeenLru,
348:     shared: Arc<Shared>,
349: }
350: 
351: impl ThumbCache {
352:     pub fn new(cache_mb: u64, pool: usize) -> Self {
353:         let dir = disk_dir();
354:         let _ = std::fs::create_dir_all(&dir);
355:         let shared = Arc::new(Shared {
356:             state: Mutex::new(QueueState::default()),
357:             cv: Condvar::new(),
358:             generation: AtomicU64::new(1),
359:             cancelled: AtomicBool::new(false),
360:         });
361:         #[cfg(not(target_arch = "wasm32"))]
362:         {
363:             let cache_dir = dir.clone();
364:             for _ in 0..THUMB_WORKERS {
365:                 let (s, d) = (shared.clone(), cache_dir.clone());
366:                 let _ = std::thread::spawn(move || {
367:                     thumb_worker(s, d);
368:                 });
369:             }
370:         }
371:         Self {
372:             disk: DiskLru::new(dir, cache_mb),
373:             big: Lru::new(pool.max(1)),
374:             fails: HashMap::new(),
375:             seen: SeenLru::new(),
376:             shared,
377:         }
378:     }
379: 
380:     /// Test / inline constructor without worker threads (wasm + unit tests).
381:     pub fn new_inline(cache_mb: u64, pool: usize, dir: PathBuf) -> Self {
382:         let _ = std::fs::create_dir_all(&dir);
383:         Self {
384:             disk: DiskLru::new(dir, cache_mb),
385:             big: Lru::new(pool.max(1)),
386:             fails: HashMap::new(),
387:             seen: SeenLru::new(),
388:             shared: Arc::new(Shared {
389:                 state: Mutex::new(QueueState::default()),
390:                 cv: Condvar::new(),
391:                 generation: AtomicU64::new(1),
392:                 cancelled: AtomicBool::new(false),
393:             }),
394:         }
395:     }
396: 
397:     fn fail_key(path: &str, mtime_ns: i64) -> String {
398:         let mut h = blake3::Hasher::new();
399:         h.update(path.as_bytes());
400:         h.update(&mtime_ns.to_le_bytes());
401:         h.finalize().to_string()[..32].to_string()
402:     }
403: 
404:     pub fn is_failed_out(&self, path: &str, mtime_ns: i64) -> bool {
405:         self.fails.get(&Self::fail_key(path, mtime_ns)).copied().unwrap_or(0) >= FAIL_AFTER
406:     }
407: 
408:     pub fn record_fail(&mut self, path: &str, mtime_ns: i64) {
409:         *self.fails.entry(Self::fail_key(path, mtime_ns)).or_insert(0) += 1;
410:     }
411: 
412:     /// Forget cached state for `path` after an edit (new key anyway via
413:     /// mtime/generation; this clears the seen hint).
414:     pub fn forget(&mut self, path: &str) {
415:         self.seen.forget_containing(path);
416:         self.fails.retain(|k, _| !k.contains(path));
417:         self.seen.remove(path);
418:     }
419: 
420:     pub fn generation(&self) -> u64 {
421:         self.shared.generation.load(Ordering::SeqCst)
422:     }
423: 
424:     /// Enqueue one job (viewer-zoom / focused cell). Dedupe via `seen`.
425:     /// Returns false when the key was already requested (dedupe hit).
426:     pub fn request_one(&mut self, job: ThumbJob) -> bool {
427:         if !self.seen.insert(job.key.clone()) {
428:             return false;
429:         }
430:         self.enqueue(job);
431:         true
432:     }
433: 
434:     fn enqueue(&self, job: ThumbJob) {
435:         let mut st = self.shared.lock_state();
436:         st.queue.push(job);
437:         self.shared.cv.notify_one();
438:     }
439: 
440:     /// Visible-only: **replace** the pending queue with the current
441:     /// viewport (+ the single focused cell the caller includes). Anything
442:     /// off-screen is never decoded (it is not in the vec). Bumps the
443:     /// generation so in-flight stale results are dropped by [`poll`].
444:     /// LIFO: the last visible cell (usually just-scrolled) decodes first.
445:     pub fn rebuild_visible(&mut self, jobs: Vec<ThumbJob>) {
446:         self.shared.generation.fetch_add(1, Ordering::SeqCst);
447:         self.shared.cancelled.store(false, Ordering::SeqCst);
448:         let gen = self.shared.generation.load(Ordering::SeqCst);
449:         // Rebuild, never accumulate: any pending job for a cell that
450:         // scrolled off-screen is dropped here, so off-screen cells are
451:         // never decoded.
452:         {
453:             let mut st = self.shared.lock_state();
454:             st.queue.clear();
455:         }
456:         for j in jobs {
457:             self.seen.insert(j.key.clone());
458:             let mut j = j;
459:             j.generation = gen;
460:             self.enqueue(j);
461:         }
462:     }
463: 
464:     /// Cancel all pending decoding (dialog dismissed, app hidden).
465:     /// In-flight jobs finish but their results are dropped at [`poll`]
466:     /// if the generation moved — and no new work starts.
467:     pub fn cancel(&self) {
468:         self.shared.cancelled.store(true, Ordering::SeqCst);
469:         self.shared.generation.fetch_add(1, Ordering::SeqCst);
470:         let mut st = self.shared.lock_state();
471:         st.queue.clear();
472:         self.shared.cv.notify_all();
473:     }
474: 
475:     /// Drain finished thumbnails. On wasm (no workers) decodes up to
476:     /// 2 pending jobs inline. Stale-generation results are dropped.
477:     pub fn poll(&self) -> Vec<ThumbResult> {
478:         #[cfg(target_arch = "wasm32")]
479:         {
480:             self.pump_inline(2);
481:         }
482:         let gen = self.shared.generation.load(Ordering::SeqCst);
483:         let mut st = self.shared.lock_state();
484:         let all: Vec<ThumbResult> = std::mem::take(&mut st.out);
485:         all.into_iter().filter(|_| gen == self.shared.generation.load(Ordering::SeqCst)).collect()
486:         // NOTE: a job decoded before a rebuild carries a generation older
487:         // than `gen`; workers already re-check at decode time, and the
488:         // filter above drops anything produced across a rebuild boundary
489:         // that the UI no longer wants (no flicker of off-screen cells).
490:     }
491: 
492:     /// Decode up to `n` queued jobs synchronously (wasm / tests).
493:     pub fn pump_inline(&self, n: usize) {
494:         for _ in 0..n {
495:             let job = {
496:                 let mut st = self.shared.lock_state();
497:                 st.queue.pop() // LIFO
498:             };
499:             let Some(job) = job else { break };
500:             if self.shared.cancelled.load(Ordering::SeqCst) {
501:                 break;
502:             }
503:             if job.generation != self.shared.generation.load(Ordering::SeqCst) {
504:                 continue; // stale
505:             }
506:             if let Some(res) = decode_job(&job, &self.disk.dir) {
507:                 let mut st = self.shared.lock_state();
508:                 st.out.push(res);
509:             }
510:         }
511:     }
512: 
513:     /// Number of pending jobs (for tests / progress bars).
514:     pub fn pending(&self) -> usize {
515:         self.shared.lock_state().queue.len()
516:     }
517: 
518:     /// Procedural fallback tile (eiga test-card pattern) — never black (§4.7).
519:     /// Distinct from both the loading skeleton and the broken tile: this is
520:     /// the honest "indexed, no preview" state with a reason.
521:     pub fn fallback_tile(reason: &str) -> (Vec<u8>, String) {
522:         // 2×2 checker standing in for a drawn test card; the reason travels
523:         // with the tile so the UI can show "No preview — <reason>".
524:         let mut rgba = Vec::with_capacity(16);
525:         for i in 0..16 {
526:             rgba.push(if i % 8 < 4 { 120 } else { 200 });
527:         }
528:         (rgba, reason.to_string())
529:     }
530: }
