532: #[cfg(not(target_arch = "wasm32"))]
533: fn thumb_worker(shared: Arc<Shared>, cache_dir: PathBuf) {
534:     loop {
535:         let job = {
536:             let mut st = shared.lock_state();
537:             loop {
538:                 if shared.cancelled.load(Ordering::SeqCst) {
539:                     // Wait until cancel clears / a new generation starts.
540:                     st = match shared.cv.wait(st) {
541:                         Ok(g) => g,
542:                         Err(e) => e.into_inner(),
543:                     };
544:                     st.queue.clear();
545:                     continue;
546:                 }
547:                 if let Some(j) = st.queue.pop() {
548:                     break j; // LIFO
549:                 }
550:                 st = match shared.cv.wait(st) {
551:                     Ok(g) => g,
552:                     Err(e) => e.into_inner(),
553:                 };
554:             }
555:         };
556:         if shared.cancelled.load(Ordering::SeqCst) {
557:             continue;
558:         }
559:         if job.generation != shared.generation.load(Ordering::SeqCst) {
560:             continue; // stale after rebuild_visible / cancel
561:         }
562:         if let Some(res) = decode_job(&job, &cache_dir) {
563:             if job.generation == shared.generation.load(Ordering::SeqCst) {
564:                 let mut st = shared.lock_state();
565:                 st.out.push(res);
566:             }
567:         }
568:     }
569: }
