571: /// Decode one job: disk → image decode / ffmpeg still → disk store → RGBA.
572: /// Returns `None` when undecodable (caller shows the declared tile).
573: /// Bounded reads (48 MB); never a black tile.
574: pub fn decode_job(job: &ThumbJob, cache_dir: &Path) -> Option<ThumbResult> {
575:     let disk_path = disk_path_for(cache_dir, &job.key);
576:     // Disk hit (key already has mtime — a hit is the current bytes).
577:     if let Ok(png) = std::fs::read(&disk_path) {
578:         if let Some((w, h, rgba)) = bytes_to_thumb(&png, job.edge) {
579:             return Some(ThumbResult {
580:                 key: job.key.clone(),
581:                 path: job.path.clone(),
582:                 w,
583:                 h,
584:                 rgba,
585:                 from_disk: true,
586:                 video_frame: false,
587:             });
588:         }
589:     }
590:     // Image path (bounded read).
591:     let img_bytes = read_bounded(&job.path, MAX_DECODE_BYTES)?;
592:     if let Some((w, h, rgba)) = bytes_to_thumb(&img_bytes, job.edge) {
593:         // Store the *decoded* thumbnail as PNG so the next hit is cheap.
