623: fn read_bounded(path: &str, max: usize) -> Option<Vec<u8>> {
624:     use std::io::Read;
625:     let f = std::fs::File::open(path).ok()?;
626:     let mut buf = Vec::new();
627:     f.take(max as u64).read_to_end(&mut buf).ok()?;
628:     if buf.is_empty() {
629:         return None;
630:     }
631:     Some(buf)
632: }
633: 
634: fn bytes_to_thumb(bytes: &[u8], edge: u32) -> Option<(u32, u32, Vec<u8>)> {
635:     let img = image::load_from_memory(bytes).ok()?;
636:     // Never upscale a thumbnail past the source (no blurry tiles).
637:     let longest = img.width().max(img.height()).max(1);
638:     let e = edge.max(1).min(longest);
639:     let t = img.thumbnail(e, e).to_rgba8();
640:     Some((t.width(), t.height(), t.into_raw()))
641: }
642: 
643: fn store_thumb(cache_dir: &Path, key: &str, src_bytes: &[u8], edge: u32) {
644:     let Ok(img) = image::load_from_memory(src_bytes) else { return };
645:     let longest = img.width().max(img.height()).max(1);
646:     let e = edge.max(1).min(longest);
647:     let t = img.thumbnail(e, e);
648:     let path = disk_path_for(cache_dir, key);
649:     if let Some(parent) = path.parent() {
650:         let _ = std::fs::create_dir_all(parent);
651:     }
652:     let mut buf: Vec<u8> = Vec::new();
653:     let mut cur = std::io::Cursor::new(&mut buf);
654:     if t.write_to(&mut cur, image::ImageFormat::Png).is_ok() {
655:         let _ = std::fs::write(&path, &buf);
656:     }
657: }
658: 
659: /// ffmpeg `-ss 0.7` single frame → disk cache → RGBA thumbnail.
660: /// No ffmpeg / no valid frame → `None` (honest degrade, never black).
661: #[cfg(not(target_arch = "wasm32"))]
662: fn video_thumb_job(real_path: &str, edge: u32, cache_dir: &Path, key: &str) -> Option<(u32, u32, Vec<u8>)> {
663:     let out = std::process::Command::new("ffmpeg")
664:         .args(video_ffmpeg_args(real_path))
665:         .output()
666:         .ok()?;
667:     if !out.status.success() || out.stdout.is_empty() {
668:         return None;
669:     }
670:     let (w, h, rgba) = bytes_to_thumb(&out.stdout, edge)?;
671:     // Cache the *thumbnail* (not the raw frame) so repeat hits stay small.
672:     let path = disk_path_for(cache_dir, key);
673:     if let Some(parent) = path.parent() {
674:         let _ = std::fs::create_dir_all(parent);
675:     }
676:     if let Ok(img) = image::load_from_memory(&out.stdout) {
677:         let longest = img.width().max(img.height()).max(1);
678:         let e = edge.max(1).min(longest);
679:         let t = img.thumbnail(e, e);
680:         let mut buf: Vec<u8> = Vec::new();
681:         let mut cur = std::io::Cursor::new(&mut buf);
682:         if t.write_to(&mut cur, image::ImageFormat::Png).is_ok() {
683:             let _ = std::fs::write(&path, &buf);
684:         }
685:     }
686:     Some((w, h, rgba))
687: }
