30:     pub fn factor(&self, canvas: f32, img: f32) -> f32 {
31:         match self {
32:             Zoom::Fit => if img > 0.0 { (canvas / img).min(1.6) * 0.96 } else { 1.0 },
33:             Zoom::Fill => if img > 0.0 { (canvas / img).max(1.0) } else { 1.0 },
34:             Zoom::P100 => 1.0,
35:             Zoom::P200 => 2.0,
