52: pub fn zoom_to_cursor(pan: f32, cursor: f32, old_zoom: f32, new_zoom: f32) -> f32 {
53:     if old_zoom <= 0.0 {
54:         return pan;
55:     }
56:     cursor - (cursor - pan) * (new_zoom / old_zoom)
57: }
