+    "  With no DIR the library defaults to the Pictures directory\n",
+    "  (or the home directory when no Pictures dir exists).\n",
+    "\nEXAMPLES:\n",
+    "  smart-photos\n",
+    "  smart-photos ~/Pictures\n",
+    "  smart-photos --scan ~/Pictures            # headless, CI-safe\n",
+    "  smart-photos --smoke ~/Pictures           # headless launch smoke\n",
+    "\nEXIT CODES: 0 ok · 1 scan/window failure (logged) · 2 usage error.\n",
+    "NOTE: `--dir`/positional roots apply to the standalone window\n",
+    "  (default build). Under `--features shared-ui` the shared frontend\n",
+    "  owns the window and scans the suite home; roots are ignored.\n",
+);
+
+/// Crate version (workspace version).
+pub const VERSION: &str = env!("CARGO_PKG_VERSION");
+
+/// Parsed command line. `argv` excludes the program name.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub enum ArgsOutcome {
+    Help,
+    Version,
+    Scan { roots: Vec<String> },
+    Smoke { roots: Vec<String> },
+    Run { roots: Vec<String> },
+    Error(String),
+}
+
+/// Parse CLI args (excludes argv[0]). `--scan`/`--smoke` select the headless
+/// mode; anything else (or nothing) selects the window. Empty roots in
+/// Scan/Smoke/Run resolve to [`default_roots`].
+pub fn parse_args(argv: &[String]) -> ArgsOutcome {
+    let mut roots: Vec<String> = Vec::new();
+    let mut mode_scan = false;
+    let mut mode_smoke = false;
+    let mut i = 0usize;
+    while i < argv.len() {
+        let a = &argv[i];
+        match a.as_str() {
+            "--" => {
+                for rest in &argv[i + 1..] {
+                    roots.push(rest.clone());
+                }
+                break;
+            }
+            "-h" | "--help" | "help" => return ArgsOutcome::Help,
+            "-V" | "--version" | "version" => return ArgsOutcome::Version,
+            "--scan" => mode_scan = true,
+            "--smoke" => mode_smoke = true,
+            "--dir" => {
+                let Some(d) = argv.get(i + 1) else {
+                    return ArgsOutcome::Error("--dir needs a directory argument".into());
+                };
+                roots.push(d.clone());
+                i += 1;
+            }
+            s if s.starts_with("--dir=") => {
+                let d = s.trim_start_matches("--dir=");
+                if d.is_empty() {
+                    return ArgsOutcome::Error("--dir= needs a directory".into());
+                }
+                roots.push(d.to_string());
+            }
+            s if s.starts_with('-') && s != "-" => {
+                return ArgsOutcome::Error(format!("unknown option: {s} (try --help)"));
+            }
+            _ => roots.push(a.clone()),
+        }
+        i += 1;
+    }
+    if mode_scan && mode_smoke {
+        return ArgsOutcome::Error("--scan and --smoke are mutually exclusive".into());
+    }
+    let roots = if roots.is_empty() { default_roots() } else { roots };
+    if mode_scan {
+        ArgsOutcome::Scan { roots }
+    } else if mode_smoke {
+        ArgsOutcome::Smoke { roots }
+    } else {
+        ArgsOutcome::Run { roots }
+    }
+}
+
+/// Default library roots: Pictures when present, else home, else `/`.
+pub fn default_roots() -> Vec<String> {
+    if let Some(p) = dirs::picture_dir() {
+        let s = p.to_string_lossy().to_string();
+        if std::path::Path::new(&s).is_dir() {
+            return vec![s];
+        }
+    }
+    let home = dirs::home_dir().map(|p| p.to_string_lossy().to_string());
+    match home {
+        Some(h) if std::path::Path::new(&h).is_dir() => vec![h],
+        _ => vec!["/".to_string()],
+    }
+}
+
+/// Result of a headless [`run_headless_scan`]/[`smoke_check`] call.
+#[derive(Clone, Debug)]
+pub struct ScanSummary {
+    pub roots: Vec<String>,
+    pub photos: usize,
+    pub skipped: usize,
+    pub partial: bool,
+}
+
+/// Headless library scan over `roots` (never opens a window).
+/// Fails with a plain message when there is nothing to scan or a root is
+/// not a directory — never a silent success.
+pub fn run_headless_scan(roots: &[String]) -> Result<ScanSummary, String> {
+    if roots.is_empty() {
+        return Err("no library roots to scan".into());
+    }
+    for r in roots {
+        if !std::path::Path::new(r).is_dir() {
+            return Err(format!("not a directory: {r}"));
+        }
+    }
+    let gw = protocol::LocalGateway::default();
+    let sc = scan::Scanner {
+        gateway: &gw,
+        config: scan::ScanConfig { roots: roots.to_vec(), ..Default::default() },
+        cancelled: false,
+        published_total: 0,
+    };
+    let s = sc.scan();
+    Ok(ScanSummary {
+        roots: roots.to_vec(),
+        photos: s.photos,
+        skipped: s.skipped,
+        partial: s.partial,
+    })
+}
+
+/// Launch smoke: headless scan + one real thumbnail decode through the
+/// shared disk cache. Proves the launch path end-to-end (settings load,
+/// scan, decode, cache store) without needing a display. `Ok` reports
+/// `thumb_ok` honestly: an empty library is a successful scan with
+/// `thumb_note` saying there was nothing to decode.
+#[derive(Clone, Debug)]
+pub struct SmokeReport {
+    pub scan: ScanSummary,
+    pub thumb_ok: bool,
+    pub thumb_note: String,
+    pub cache_key_sample: String,
+}
+
+pub fn smoke_check(roots: &[String]) -> Result<SmokeReport, String> {
+    let summary = run_headless_scan(roots)?;
+    let gw = protocol::LocalGateway::default();
+    let sc = scan::Scanner {
+        gateway: &gw,
+        config: scan::ScanConfig { roots: roots.to_vec(), ..Default::default() },
+        cancelled: false,
+        published_total: 0,
+    };
+    let snap = sc.scan();
+    if snap.records.is_empty() {
+        return Ok(SmokeReport {
+            scan: summary,
+            thumb_ok: false,
+            thumb_note: "library empty — scan succeeded, no photo to decode".into(),
+            cache_key_sample: String::new(),
+        });
+    }
+    let rec = &snap.records[0];
+    let key = thumb_cache::cache_key(
+        &rec.path,
+        256,
+        rec.mtime_ns,
+        1,
+        rec.edit_generation,
+    );
+    let job = thumb_cache::ThumbJob {
+        path: rec.path.clone(),
+        key: key.clone(),
+        rung: 256,
+        edge: 256,
+        generation: 1,
+    };
+    // Same shared disk dir the window uses (~/.cache/smart-files/thumbs).
+    let dir = thumb_cache::disk_dir();
+    let _ = std::fs::create_dir_all(&dir);
+    let decoded = thumb_cache::decode_job(&job, &dir);
+    let (thumb_ok, thumb_note) = match decoded {
+        Some(r) => (
+            r.rgba.len() == (r.w as usize) * (r.h as usize) * 4,
+            format!(
+                "decoded {} ({}×{}, {})",
+                rec.name,
+                r.w,
+                r.h,
+                if r.from_disk { "disk cache hit" } else { "fresh decode" }
+            ),
+        ),
+        None => (false, format!("undeodable (declared tile): {}", rec.name)),
+    };
+    Ok(SmokeReport { scan: summary, thumb_ok, thumb_note, cache_key_sample: key })
+}
+
+/// Standalone eframe window (default build, feature `shared-ui` off).
+/// Wraps one [`PhotoApp`]: the library is scanned once at creation
+/// (bounded, honest partial state), thumbnails decode through the shared
+/// [`thumb_cache::ThumbCache`] worker pipeline, and undecodable entries
+/// show the declared fallback tile — never black. Uses egui's default
+/// fonts (the shared icon set lives in `smart-ui-egui`, read-only).
+#[cfg(not(feature = "shared-ui"))]
+pub struct PhotosWindow {
+    app: PhotoApp,
+    roots: Vec<String>,
+    scan_line: String,
+    textures: std::collections::HashMap<String, eframe::egui::TextureHandle>,
+    failed: std::collections::HashSet<String>,
+    queued: std::collections::HashSet<String>,
+    selected: Option<String>,
+    fallback: Option<eframe::egui::TextureHandle>,
+}
+
+#[cfg(not(feature = "shared-ui"))]
+impl PhotosWindow {
+    pub fn new(roots: Vec<String>) -> Self {
+        let roots = if roots.is_empty() { default_roots() } else { roots };
+        let gw = protocol::LocalGateway::default();
+        let (records, scanned, skipped, partial) = {
+            let sc = scan::Scanner {
+                gateway: &gw,
+                config: scan::ScanConfig { roots: roots.clone(), ..Default::default() },
+                cancelled: false,
+                published_total: 0,
+            };
+            let snap = sc.scan();
+            (snap.records, snap.photos, snap.skipped, snap.partial)
+        };
+        let mut app = PhotoApp::new(Box::new(gw));
+        app.library = records;
+        app.photos.scanned = true;
+        // Queue thumbnails for the first cells (workers decode off the UI
+        // thread; off-screen cells are simply never requested here).
+        const QUEUE_CAP: usize = 200;
+        let mut jobs = Vec::new();
+        for rec in app.library.iter().take(QUEUE_CAP) {
+            if rec.kind != model::PhotoKind::Image {
+                continue;
+            }
+            let key = thumb_cache::cache_key(
+                &rec.path,
+                256,
+                rec.mtime_ns,
+                1,
+                rec.edit_generation,
+            );
+            jobs.push(thumb_cache::ThumbJob {
+                path: rec.path.clone(),
+                key,
+                rung: 256,
+                edge: 256,
+                generation: 0,
+            });
+        }
+        let mut queued: std::collections::HashSet<String> = jobs.iter().map(|j| j.path.clone()).collect();
+        app.thumbs.rebuild_visible(jobs);
+        let scan_line = format!(
+            "{scanned} photos · {skipped} skipped · roots: {} · partial: {partial}",
+            roots.join(", ")
+        );
+        Self {
+            app: app,
+            roots: roots,
+            scan_line: scan_line,
+            textures: std::collections::HashMap::new(),
+            failed: std::collections::HashSet::new(),
+            queued: std::mem::take(&mut queued),
+            selected: None,
+            fallback: None,
+        }
+    }
+
+    fn filtered(&self) -> Vec<&model::PhotoRecord> {
+        let q = self.app.photos.search.trim().to_lowercase();
+        let mut v: Vec<&model::PhotoRecord> = self
+            .app
+            .library
+            .iter()
+            .filter(|r| q.is_empty() || r.name.to_lowercase().contains(&q))
+            .collect();
+        match self.app.photos.sort {
+            1 => v.sort_by_key(|r| r.mtime_ns),
+            2 => v.sort_by(|a, b| a.name.cmp(&b.name)),
+            3 => v.sort_by(|a, b| b.size.cmp(&a.size)),
+            _ => v.sort_by_key(|r| std::cmp::Reverse(r.mtime_ns)),
+        }
+        v
+    }
+
+    fn no_preview_reason(rec: &model::PhotoRecord) -> &'static str {
+        match rec.kind {
+            model::PhotoKind::Raw => "RAW indexed, no preview",
+            model::PhotoKind::Video => "No preview — video still unavailable",
+            model::PhotoKind::Image => "No preview — undecodable",
+        }
+    }
+}
+
+#[cfg(not(feature = "shared-ui"))]
+impl eframe::App for PhotosWindow {
+    fn update(&mut self, ctx: &eframe::egui::Context, _frame: &mut eframe::Frame) {
+        let egui = eframe::egui;
+        // Drain finished thumbnails into GPU textures.
+        for r in self.app.thumbs.poll() {
+            self.queued.remove(&r.path);
+            let ci = egui::ColorImage::from_rgba_unmultiplied([r.w as usize, r.h as usize], &r.rgba);
+            let tex = ctx.load_texture(
+                format!("smart-photos-thumb-{}", r.path),
+                ci,
+                egui::TextureOptions::LINEAR,
+            );
+            self.textures.insert(r.path.clone(), tex);
+        }
+        // When the queue drains, anything still without a texture failed.
+        if self.app.thumbs.pending() == 0 {
+            for p in self.queued.clone() {
+                if !self.textures.contains_key(&p) {
+                    self.failed.insert(p);
+                }
+            }
+            self.queued.clear();
+        }
+        if self.fallback.is_none() {
+            let (tile, _reason) = thumb_cache::ThumbCache::fallback_tile("standby");
+            let ci = egui::ColorImage::from_rgba_unmultiplied([2usize, 2usize], &tile);
+            self.fallback = Some(ctx.load_texture(
+                "smart-photos-fallback",
+                ci,
+                egui::TextureOptions::LINEAR,
+            ));
+        }
+        let fallback = self.fallback.clone().expect("fallback texture just created");
+
+        egui::TopBottomPanel::top("smart-photos-top").show(ctx, |ui| {
+            ui.heading("Smart Photos (standalone)");
+            ui.label(self.scan_line.clone());
+            let shown = self.filtered().len();
+            ui.label(format!("{} in view · click a cell for details",
+                shown,
+            ));
+        });
+        egui::CentralPanel::default().show(ctx, |ui| {
+            let mut search = self.app.photos.search.clone();
+            ui.horizontal(|ui| {
+                ui.label("Search");
+                ui.text_edit_singleline(&mut search);
+                if ui.button("Clear").clicked() {
+                    search.clear();
+                }
+                let sort_label = match self.app.photos.sort {
+                    1 => "Oldest",
+                    2 => "Name",
+                    3 => "Size",
+                    _ => "Newest",
+                };
+                if ui.button(format!("Sort: {sort_label}")).clicked() {
+                    self.app.photos.sort = (self.app.photos.sort + 1) % 4;
+                }
+            });
+            self.app.photos.search = search;
+            let list = self.filtered();
+            // Bounded grid: first 600 cells (L10 — never build 50k widgets).
+            const GRID_CAP: usize = 600;
+            let capped = list.len().min(GRID_CAP);
+            if list.len() > GRID_CAP {
+                ui.label(format!("showing first {GRID_CAP} of {} — search to narrow", list.len()));
+            }
+            let avail = ui.available_width();
+            let cols = (avail / 148.0).floor().max(1.0) as usize;
+            egui::ScrollArea::vertical()
+                .auto_shrink([false, false])
+                .show_rows(ui, capped, 148.0, |ui, rows| {
+                    for i in rows {
+                        let rec = list[i];
+                        let is_sel = self.selected.as_ref() == Some(&rec.path);
+                        let cell = ui.vertical(|ui| {
+                            let tex = self.textures.get(&rec.path).map(|t| t.id());
+                            let reason = Self::no_preview_reason(rec);
+                            let img = match tex {
+                                Some(id) => {
+                                    let img = egui::Image::new((id, egui::vec2(128.0, 96.0)))
+                                        .fit_to_exact_size(egui::vec2(128.0, 96.0));
+                                    ui.add(img)
+                                }
+                                None => {
+                                    let img = egui::Image::new((fallback.id(), egui::vec2(128.0, 96.0)))
+                                        .fit_to_exact_size(egui::vec2(128.0, 96.0));
+                                    let resp = ui.add(img);
+                                    let note = if self.failed.contains(&rec.path) {
+                                        reason.to_string()
+                                    } else if self.queued.contains(&rec.path) {
+                                        "loading …".to_string()
+                                    } else {
+                                        reason.to_string()
+                                    };
+                                    ui.label(note);
+                                    resp
+                                }
+                            };
+                            ui.label(format!("{} · {}", rec.name, match rec.kind {
+                                model::PhotoKind::Image => "image",
+                                model::PhotoKind::Video => "video",
+                                model::PhotoKind::Raw => "RAW",
+                            }));
+                            img
+                        });
+                        if cell.clicked() {
+                            self.selected = Some(rec.path.clone());
+                        }
+                    }
+                });
+            if let Some(sel) = self.selected.clone() {
+                let rec = self.app.library.iter().find(|r| r.path == sel);
+                match rec {
+                    Some(rec) => {
+                        ui.separator();
+                        ui.label(format!(
+                            "{} · {} · {} · {} · taken: {} ({}) · {:.1} KiB",
+                            rec.name,
+                            rec.path,
+                            match rec.kind {
+                                model::PhotoKind::Image => "image",
+                                model::PhotoKind::Video => "video",
+                                model::PhotoKind::Raw => "RAW",
+                            },
+                            format!("{:?}", rec.dims),
+                            rec.taken_at.map(|t| t.to_string()).unwrap_or_else(|| "unknown".into()),
+                            rec.taken_source.sentence(),
+                            rec.size as f64 / 1024.0,
+                        ));
+                        ui.label("Standalone preview — the full viewer/editor is the shared frontend (feature shared-ui).");
+                    }
+                    None => {
+                        self.selected = None;
+                    }
+                }
+            }
+            let _ = cols;
+            ui.separator();
+            ui.label(format!(
+                "roots: {} · close the window to quit · headless: smart-photos --scan / --smoke",
+                self.roots.join(", ")
+            ));
+        });
+    }
+}
