                                        .fit_to_exact_size(egui::vec2(128.0, 96.0));
                                    let resp = ui.add(img);
                                    let note = if self.failed.contains(&rec.path) {
                                        reason.to_string()
                                    } else if self.queued.contains(&rec.path) {
                                        "loading …".to_string()
                                    } else {
                                        reason.to_string()
                                    };
                                    ui.label(note);
                                    resp
                                }
                            };
                            ui.label(format!("{} · {}", rec.name, match rec.kind {
                                model::PhotoKind::Image => "image",
                                model::PhotoKind::Video => "video",
                                model::PhotoKind::Raw => "RAW",
                            }));
                            img
                        });
