//! Smart Photos binary: parses args, then either runs headless
//! (--help / --version / --scan / --smoke, exit 0/1/2, no display) or
//! opens the window. A window failure (no display) is logged to stderr
//! with exit 1 — never a silent success.

use smart_photos::{ArgsOutcome, HELP_TEXT, VERSION};

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    match smart_photos::parse_args(&argv) {
        ArgsOutcome::Help => {
            print!("{HELP_TEXT}");
        }
        ArgsOutcome::Version => {
            println!("smart-photos {VERSION}");
        }
        ArgsOutcome::Scan { roots } => match smart_photos::run_headless_scan(&roots) {
            Ok(s) => {
                println!(
                    "smart-photos scan: {} photos, {} skipped, partial: {}",
                    s.photos, s.skipped, s.partial
                );
                println!("roots: {}", s.roots.join(", "));
            }
            Err(e) => {
                eprintln!("smart-photos: scan failed: {e}");
                std::process::exit(1);
            }
        },
        ArgsOutcome::Smoke { roots } => match smart_photos::smoke_check(&roots) {
            Ok(r) => {
                println!(
                    "smart-photos smoke: {} photos, {} skipped, partial: {}",
                    r.scan.photos, r.scan.skipped, r.scan.partial
                );
                println!("thumb: ok={} {}", r.thumb_ok, r.thumb_note);
                if !r.cache_key_sample.is_empty() {
                    println!("cache-key: {}", r.cache_key_sample);
                }
                if !r.thumb_ok && r.scan.photos > 0 {
                    std::process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("smart-photos: smoke failed: {e}");
                std::process::exit(1);
            }
        },
        ArgsOutcome::Run { roots } => {
            #[cfg(feature = "shared-ui")]
            {
                // The shared frontend owns the window and scans the suite
                // home — standalone roots do not apply here.
                let _ = &roots;
                eprintln!("note: --dir ignored under shared-ui; shared frontend scans the suite home");
                if let Err(e) = smart_photos::run_native() {
                    eprintln!("smart-photos: window failed to open: {e:?}");
                    eprintln!("headless check (no display needed): smart-photos --smoke");
                    std::process::exit(1);
                }
            }
            #[cfg(not(feature = "shared-ui"))]
            if let Err(e) = smart_photos::run_native_with_roots(roots) {
                eprintln!("smart-photos: window failed to open: {e:?}");
                eprintln!("headless check (no display needed): smart-photos --smoke");
                std::process::exit(1);
            }
        }
        ArgsOutcome::Error(msg) => {
            eprintln!("smart-photos: {msg}");
            eprint!("{HELP_TEXT}");
            std::process::exit(2);
        }
    }
}

